fn permits(value: Option<u16>, ceiling: u16) -> bool {
    match value {
        None => true,
        Some(n) => n > 0 && n <= ceiling,
    }
}
fn main() {
    assert!(permits(None, 0));
    assert!(permits(Some(7), 7));
    assert!(!permits(Some(0), 7));
    assert!(!permits(Some(8), 7));
    println!("same contract on old and current Rust");
}

